// a random size and heading; oaks lower down, conifers higher up
@pscale = fit(rand(@ptnum, seed, 7), 0, 1, 0.75, 1.25);
f@yaw = 360 * rand(@ptnum, seed, 6);
const oak = 0.7 - 0.55 * clamp(@height / relief, 0, 1), u = rand(@ptnum, seed, 5);
s@variant = u < oak ? 'oak' : u < oak + (1 - oak) * 0.5 ? 'pine' : 'fir';
// whole trees stay on the terrain (4.5 m: the widest crown, turned, at scale 1) and off ground steeper than max_slope
const edge = size / 2 - 4.5 * @pscale;
if (Math.abs(@P.x) > edge || Math.abs(@P.z) > edge || @slope > max_slope) removepoint(0, @ptnum);

// three shapes, a random size and heading
@pscale = fit(rand(@ptnum, seed, 11), 0, 1, 0.7, 1.6);
f@yaw = 360 * rand(@ptnum, seed, 10);
s@variant = pick(['boulder', 'slab', 'stone'], rand(@ptnum, seed, 9));
// whole rocks stay on the terrain (3.1 m: the largest rock, turned and tilted, at scale 1)
const edge = size / 2 - 3.1 * @pscale;
if (Math.abs(@P.x) > edge || Math.abs(@P.z) > edge) removepoint(0, @ptnum);

// the ground under each instance, read from the terrain's samples (grid points, row by row), each cell cut along its (0,0)-(1,1) diagonal as a game engine's landscape draws it
const n = Math.round(Math.sqrt(npoints(1))), o = point(1, 'P', 0), cell = point(1, 'P', 1)[0] - o[0];
const fx = (@P.x - o[0]) / cell, fz = (@P.z - o[2]) / cell;
const i = clamp(Math.floor(fx), 0, n - 2), j = clamp(Math.floor(fz), 0, n - 2), u = fx - i, v = fz - j;
const h = (a, b) => point(1, 'P', (j + b) * n + i + a)[1];
const y = u >= v ? h(0, 0) + u * (h(1, 0) - h(0, 0)) + v * (h(1, 1) - h(1, 0)) : h(0, 0) + v * (h(0, 1) - h(0, 0)) + u * (h(1, 1) - h(0, 1));
f@ground_gap = @P.y - y;

// how far the instance reaches from the centre in X or Z
const b = primintrinsic(0, 'bounds', @primnum);
f@reach = Math.max(-b[0], b[1], -b[4], b[5]);

// the ground under each instance, read from the terrain's samples (grid points, row by row), each cell cut along its (0,0)-(1,1) diagonal as a game engine's landscape draws it
const n = Math.round(Math.sqrt(npoints(1))), o = point(1, 'P', 0), cell = point(1, 'P', 1)[0] - o[0];
const fx = (@P.x - o[0]) / cell, fz = (@P.z - o[2]) / cell;
const i = clamp(Math.floor(fx), 0, n - 2), j = clamp(Math.floor(fz), 0, n - 2), u = fx - i, v = fz - j;
const h = (a, b) => point(1, 'P', (j + b) * n + i + a)[1];
const y = u >= v ? h(0, 0) + u * (h(1, 0) - h(0, 0)) + v * (h(1, 1) - h(1, 0)) : h(0, 0) + v * (h(0, 1) - h(0, 0)) + u * (h(1, 1) - h(0, 1));
f@ground_gap = @P.y - y;

// how far the instance reaches from the centre in X or Z
const b = primintrinsic(0, 'bounds', @primnum);
f@reach = Math.max(-b[0], b[1], -b[4], b[5]);

// the paint layers as colours: grass (fresher in the valleys), forest floor, rock
const g = mix([0.3, 0.47, 0.17], [0.46, 0.55, 0.25], clamp(@height / relief, 0, 1)), f = [0.24, 0.25, 0.13], r = [0.5, 0.48, 0.45];
@Cd = add(mul(g, @grass), mul(f, @forest_floor), mul(r, @rock));
